  &reftitle.examples;



    Verificare se needle è presente in haystack


     È facile confondere i valori restituiti per "carattere trovato alla
     posizione 0" e "carattere non trovato".  Ecco come rilevare
     la differenza:



<?php
$mystring = 'Elephpant';

$pos = strrpos($mystring, "b");
if ($pos === false) { // nota: tre segni di uguale
    // non trovato...
}

?>







    Ricerca con offset


<?php
$foo = "0123456789a123456789b123456789c";

// Cerca '0' dal byte 0 (dall'inizio)
var_dump(strrpos($foo, '0', 0));

// Cerca '0' dal byte 1 (dopo il byte "0")
var_dump(strrpos($foo, '0', 1));

// Cerca '7' dal 21° byte (dopo il byte 20)
var_dump(strrpos($foo, '7', 20));

// Cerca '7' dal 29° byte (dopo il byte 28)
var_dump(strrpos($foo, '7', 28));

// Cerca '7' da destra a sinistra a partire dal 5° byte dalla fine
var_dump(strrpos($foo, '7', -5));

// Cerca 'c' da destra a sinistra a partire dal 2° byte dalla fine
var_dump(strrpos($foo, 'c', -2));

// Cerca '9c' da destra a sinistra a partire dal 2° byte dalla fine
var_dump(strrpos($foo, '9c', -2));
?>


